import{_ as a,a0 as p,w as r,s as d,ao as l,I as o,a1 as i,A as n,x as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"Hegemon：使用 Rust 編寫的模組化系統監視程序 | LCTT x X-CMD","titleTemplate":false,"description":"Hegemon：使用 Rust 編寫的模組化系統監視程序 | LCTT (201810) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Hegemon：使用 Rust 編寫的模組化系統監視程序 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Hegemon：使用 Rust 編寫的模組化系統監視程序 | LCTT (201810) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201810/20180925 Hegemon - A Modular System Monitor Application Written In Rust","title":"Hegemon：使用 Rust 編寫的模組化系統監視程序","tag":"201810","desc":""},"relativePath":"201810/20180925 Hegemon - A Modular System Monitor Application Written In Rust.md","filePath":"[post].md"}'),u={name:"201810/20180925 Hegemon - A Modular System Monitor Application Written In Rust.md"};function g(m,t,h,b,k,f){const s=p("Link");return r(),d("div",null,[t[19]||(t[19]=l('<h1 id="hegemon-使用-rust-編寫的模組化系統監視程序" tabindex="-1">Hegemon：使用 Rust 編寫的模組化系統監視程序 <a class="header-anchor" href="#hegemon-使用-rust-編寫的模組化系統監視程序" aria-label="Permalink to “Hegemon：使用 Rust 編寫的模組化系統監視程序”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/09/hegemon-720x340.png" alt=""></p><p>在類 Unix 系統中監視運行進程時，最常用的程序是 <code>top</code> 和它的增強版 <code>htop</code>。我個人最喜歡的是 <code>htop</code>。但是，開發人員不時會發布這些程序的替代品。<code>top</code> 和 <code>htop</code> 工具的一個替代品是 <code>Hegemon</code>。它是使用 Rust 語言編寫的模組化系統監視程序。</p><p>關於 Hegemon 的功能，我們可以列出以下這些：</p><ul><li>Hegemon 會監控 CPU、內存和交換頁的使用情況。</li><li>它監控系統的温度和風扇速度。</li><li>更新間隔時間可以調整。默認值為 3 秒。</li><li>我們可以通過擴展數據流來展示更詳細的圖表和其他信息。</li><li>單元測試。</li><li>乾淨的界面。</li><li>自由開源。</li></ul><h3 id="安裝-hegemon" tabindex="-1">安裝 Hegemon <a class="header-anchor" href="#安裝-hegemon" aria-label="Permalink to “安裝 Hegemon”">​</a></h3><p>確保已安裝 Rust 1.26 或更高版本。要在 Linux 發行版中安裝 Rust，請參閲以下指南：</p>',7)),o("ul",null,[o("li",null,[i(s,{href:"https://www.ostechnix.com/install-rust-programming-language-in-linux/"},{default:n(()=>[...t[0]||(t[0]=[e("在 Linux 中安裝 Rust 編程語言",-1)])]),_:1})])]),o("p",null,[t[2]||(t[2]=e("另外要安裝 ",-1)),i(s,{href:"https://github.com/lm-sensors/lm-sensors"},{default:n(()=>[...t[1]||(t[1]=[e("libsensors",-1)])]),_:1}),t[3]||(t[3]=e(" 庫。它在大多數 Linux 發行版的默認倉庫中都有。例如，你可以使用以下命令將其安裝在基於 RPM 的系統（如 Fedora）中：",-1))]),t[20]||(t[20]=l('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install lm_sensors-devel</span></span></code></pre></div><p>在像 Ubuntu、Linux Mint 這樣的基於 Debian 的系統上，可以使用這個命令安裝它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get install libsensors4-dev</span></span></code></pre></div><p>在安裝 Rust 和 libsensors 後，使用命令安裝 Hegemon：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cargo install hegemon</span></span></code></pre></div><p>安裝 hegemon 後，使用以下命令開始監視 Linux 系統中正在運行的進程：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ hegemon</span></span></code></pre></div><p>以下是 Arch Linux 桌面的示例輸出。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/09/Hegemon-in-action.gif" alt=""></p><p>要退出，請按 <code>Q</code>。</p><p>請注意，hegemon 仍處於早期開發階段，並不能完全取代 <code>top</code> 命令。它可能存在 bug 和功能缺失。如果你遇到任何 bug，請在項目的 GitHub 頁面中報告它們。開發人員計劃在即將推出的版本中引入更多功能。所以，請關注這個項目。</p><p>就是這些了。希望這篇文章有用。還有更多的好東西。敬請關注！</p><p>乾杯!</p><hr>',14)),o("p",null,[t[5]||(t[5]=e("via: ",-1)),i(s,{href:"https://www.ostechnix.com/hegemon-a-modular-system-monitor-application-written-in-rust/"},{default:n(()=>[...t[4]||(t[4]=[e("https://www.ostechnix.com/hegemon-a-modular-system-monitor-application-written-in-rust/",-1)])]),_:1})]),o("p",null,[t[10]||(t[10]=e("作者：",-1)),i(s,{href:"https://www.ostechnix.com/author/sk/"},{default:n(()=>[...t[6]||(t[6]=[e("SK",-1)])]),_:1}),t[11]||(t[11]=e(" 選題：",-1)),i(s,{href:"https://github.com/lujun9972"},{default:n(()=>[...t[7]||(t[7]=[e("lujun9972",-1)])]),_:1}),t[12]||(t[12]=e(" 譯者：",-1)),i(s,{href:"https://github.com/geekpi"},{default:n(()=>[...t[8]||(t[8]=[e("geekpi",-1)])]),_:1}),t[13]||(t[13]=e(" 校對：",-1)),i(s,{href:"https://github.com/wxy"},{default:n(()=>[...t[9]||(t[9]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[16]||(t[16]=e("本文由 ",-1)),i(s,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[14]||(t[14]=[e("LCTT",-1)])]),_:1}),t[17]||(t[17]=e(" 原創編譯，",-1)),i(s,{href:"https://linux.cn/"},{default:n(()=>[...t[15]||(t[15]=[e("Linux中國",-1)])]),_:1}),t[18]||(t[18]=e(" 榮譽推出",-1))])])}const c=a(u,[["render",g]]);export{C as __pageData,c as default};
